<script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {Search,PackageCheck,Clock,CheckCircle2,ChefHat,Truck} from 'lucide-vue-next';import {api,money} from '../api';const route=useRoute();const orderNumber=ref(route.query.order||''),phone=ref(''),order=ref(null),error=ref(''),loading=ref(false);async function track(){loading.value=true;error.value='';order.value=null;try{const {data}=await api.get('/orders/track/'+encodeURIComponent(orderNumber.value),{params:{phone:phone.value}});order.value=data}catch(e){error.value=e.response?.data?.message||'Could not find this order.'}finally{loading.value=false}}onMounted(()=>{if(route.query.order)orderNumber.value=route.query.order});const steps=[{key:'pending',label:'Order received',icon:PackageCheck},{key:'confirmed',label:'Confirmed',icon:CheckCircle2},{key:'preparing',label:'Preparing',icon:ChefHat},{key:'ready',label:'Ready / on the way',icon:Truck},{key:'completed',label:'Completed',icon:CheckCircle2}];</script>
<template><section class="track-page"><div class="track-heading"><div class="track-icon"><PackageCheck :size="28"/></div><p class="eyebrow">NO MORE GUESSING</p><h1>Track your <em>order.</em></h1><p>Enter your order number and the phone number you used at checkout.</p></div><form class="track-form" @submit.prevent="track"><label>Order number<input v-model="orderNumber" required placeholder="e.g. QB261013A1B2C3"/></label><label>Phone number<input v-model="phone" required placeholder="09xx xxx xxxx"/></label><button class="btn primary wide" :disabled="loading"><Search :size="17"/> {{loading?'Looking it up…':'Track order'}}</button><div v-if="error" class="alert">{{error}}</div></form><div v-if="order" class="track-result"><div class="result-head"><div><p class="eyebrow">ORDER DETAILS</p><h2>{{order.order_number}}</h2><p class="muted">Placed {{new Date(order.created_at).toLocaleString()}}</p></div><span class="status-pill" :class="order.status">{{order.status}}</span></div><div v-if="order.status==='cancelled'" class="alert">This order was cancelled. Please contact the store if you need help.</div><div v-else class="timeline"><div v-for="(s,i) in steps" :key="s.key" class="timeline-step" :class="{done:steps.findIndex(x=>x.key===order.status)>=i, current:order.status===s.key}"><div class="timeline-node"><component :is="s.icon" :size="17"/></div><div><b>{{s.label}}</b><small>{{s.key===order.status?'Current status':steps.findIndex(x=>x.key===order.status)>i?'Completed':'Up next'}}</small></div></div></div><div class="result-items"><div v-for="it in order.items" :key="it.id" class="result-item"><span>{{it.quantity}} × {{it.product_name}}</span><b>{{money(it.line_total)}}</b></div></div><div class="result-total"><span>Total · {{order.order_type}} · {{order.payment_method==='cod'?'Cash on delivery':'GCash'}}</span><strong>{{money(order.total)}}</strong></div></div></section></template>